import sys
import heapq

lines = [ln.strip() for ln in sys.stdin.read().splitlines() if ln.strip()]
n = int(lines[0])
deps = {}
for i in range(1, n + 1):
    parts = lines[i].split()
    deps[parts[0]] = set(parts[1:])

indeg = {t: len(deps[t]) for t in deps}
children = {t: [] for t in deps}
for t in deps:
    for d in deps[t]:
        children[d].append(t)

ready = [t for t in deps if indeg[t] == 0]
heapq.heapify(ready)
order = []
while ready:
    task = heapq.heappop(ready)
    order.append(task)
    for child in children[task]:
        indeg[child] -= 1
        if indeg[child] == 0:
            heapq.heappush(ready, child)

if len(order) != len(deps):
    print('cycle')
else:
    for task in order:
        print(task)
